# requires: ReactomePA ggplot2 jsonlite digest
here<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1])));mod<-dirname(here);root<-normalizePath(file.path(mod,'../..'));shared<-file.path(root,'skills/_shared/scripts')
for(f in c('module_kit.R','refdata_io.R','annotation_io.R','calls_check.R'))source(file.path(shared,f));source(file.path(mod,'scripts/reactomepa_ora_core.R'))
if(!requireNamespace('ReactomePA',quietly=TRUE))stop('OS_MISSING_PACKAGE: real ReactomePA engine is required for scientific smoke; no fallback or mock')
check<-function(ok,msg){if(!isTRUE(ok))stop(paste('FAIL',msg));cat('PASS',msg,'\n')};refuse<-function(expr,code){msg<-tryCatch({force(expr);'NO_ERROR'},error=conditionMessage);check(grepl(code,msg,fixed=TRUE),paste('refusal',code))}
tmp<-tempfile();dir.create(tmp);status<-system2('python3',c(shQuote(file.path(here,'prepare_acceptance.py')),shQuote(tmp)));stopifnot(status==0)
cfg<-jsonlite::fromJSON(file.path(here,'acceptance.json'),simplifyVector=FALSE);argv<-unlist(cfg$canonical$argv);argv<-gsub('{fixtures}',tmp,argv,fixed=TRUE);out<-file.path(tmp,'run');argv<-gsub('{outdir}',out,argv,fixed=TRUE)
status<-system2('Rscript',c(shQuote(file.path(mod,'scripts/run_reactomepa_ora.R')),shQuote(argv)));check(status==0,'actual CLI and renderer')
ans<-file.path(tmp,'anchors.json');status<-system2('python3',c(shQuote(file.path(here,'anchors.py')),shQuote(ans),shQuote(out)));stopifnot(status==0);z<-jsonlite::fromJSON(ans);check(z$exact_hypergeometric_max_error<1e-10,'independent exact hypergeometric');check(z$independent_bh_max_error<1e-10,'independent BH family');check(z$integer_count_max_error==0,'exact query/set/universe counts');check(z$author_selected_input_count==15,'fifteen documented author input IDs')
snap<-os_reactome_snapshot('human');check(identical(snap$manifest,jsonlite::fromJSON(file.path(tmp,'snapshot.json'),simplifyVector=FALSE))||snap$manifest$mapping_sha256==jsonlite::fromJSON(file.path(tmp,'snapshot.json'))$mapping_sha256,'stable actual resource hash')
a<-list(`refdata-registry`=file.path(tmp,'registry.json'),`refdata-id`='reactome_gene_sets',`refdata-input`=file.path(tmp,'snapshot.json'),`refdata-provenance`=file.path(tmp,'provenance.json'),organism='human');check(os_reactome_bound(a)$manifest$mapping_sha256==snap$manifest$mapping_sha256,'actual installed bytes bound')
d<-jsonlite::fromJSON(a[['refdata-input']],simplifyVector=FALSE);d$bindings[[1]]$sha256<-paste(rep('0',64),collapse='');jsonlite::write_json(d,a[['refdata-input']],auto_unbox=TRUE,pretty=TRUE);p<-jsonlite::fromJSON(a[['refdata-provenance']],simplifyVector=FALSE);p$sha256<-digest::digest(file=a[['refdata-input']],algo='sha256');jsonlite::write_json(p,a[['refdata-provenance']],auto_unbox=TRUE);refuse(os_reactome_bound(a),'OS_REFDATA_MISMATCH')
check(check_default_drift(file.path(mod,'scripts/calls_registry.json'))$ok,'actual engine default drift');check(!file.exists('Rplots.pdf'),'no device leak');unlink(tmp,recursive=TRUE);cat('SCIENTIFIC SMOKE PASSED\n')
